(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=3200,H=2400,TAU=Math.PI*2;let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2),last=0,elapsed=0,shake=0;
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rnd=(a,b)=>a+Math.random()*(b-a);
let seed=71249;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
const player={x:480,y:1280,r:14,hp:100,maxHp:100,level:1,xp:0,gold:0,relics:0,face:0,attack:0,invuln:0,speed:210};
let keys={},trees=[],rocks=[],flowers=[],enemies=[],loot=[],shots=[],particles=[],floating=[],dead=false,won=false,sound=true,showMap=true;
const landmarks=[{name:'Gloamwood',x:730,y:1120,r:600,color:'#1c3323'},{name:'Blackroot Thicket',x:1250,y:620,r:420,color:'#202d20'},{name:'Morrowfen',x:1550,y:1500,r:430,color:'#253528'},{name:'The Sable March',x:2060,y:1110,r:560,color:'#34342a'},{name:'Ember Crown',x:2620,y:1980,r:480,color:'#49352d'},{name:'Ravenfall Keep',x:2660,y:440,r:290,color:'#33252b'}];
function inForest(x,y){return Math.hypot(x-730,y-1120)<600||Math.hypot(x-1250,y-620)<420||Math.hypot(x-1550,y-1500)<430}
function onPath(x,y){const paths=[[[120,1280],[680,1250],[1100,900],[1580,880],[2060,1120],[2570,740]],[[1580,880],[2070,1440],[2580,1980]]];for(const path of paths)for(let i=1;i<path.length;i++){let [ax,ay]=path[i-1],[bx,by]=path[i],t=clamp(((x-ax)*(bx-ax)+(y-ay)*(by-ay))/((bx-ax)**2+(by-ay)**2),0,1);if(Math.hypot(x-ax-(bx-ax)*t,y-ay-(by-ay)*t)<42)return true}return false}
// Woodland silhouettes and small ground details are fixed so exploration remains coherent.
for(let i=0;i<670;i++){let x=rand()*W,y=rand()*H;if(!inForest(x,y)||onPath(x,y)||Math.hypot(x-480,y-1280)<100)continue;let r=rnd(15,35);trees.push({x,y,r,h:rnd(.8,1.35),tone:rand(),seed:rand()*8})}
for(let i=0;i<210;i++){rocks.push({x:rand()*W,y:rand()*H,r:rnd(4,13),tone:rand()})}
