function makeEnemy(type,x,y){const data={wolf:{name:'Gloam Wolf',hp:38,speed:78,r:13,xp:19,gold:4,color:'#777568',dmg:9},wraith:{name:'Murk Wraith',hp:54,speed:60,r:15,xp:30,gold:8,color:'#91aaa0',dmg:12},brute:{name:'Thornback',hp:82,speed:43,r:20,xp:43,gold:13,color:'#85804b',dmg:16},vampire:{name:'Vampire Lord Veyr',hp:510,speed:57,r:27,xp:240,gold:120,color:'#be5263',dmg:18,boss:true},dragon:{name:'The Ashen Wyrm',hp:820,speed:48,r:39,xp:450,gold:250,color:'#dc6843',dmg:25,boss:true}}[type];return {...data,type,x,y,maxHp:data.hp,attackCd:rnd(.4,1.2),hit:0,phase:0,alive:true}}
for(let i=0;i<30;i++){let x,y;do{x=rnd(200,2250);y=rnd(180,2200)}while(!inForest(x,y)||Math.hypot(x-480,y-1280)<290);enemies.push(makeEnemy(i%5===0?'brute':i%3===0?'wraith':'wolf',x,y))}
const bosses={vampire:makeEnemy('vampire',2650,445),dragon:makeEnemy('dragon',2700,1990)};bosses.vampire.alive=false;bosses.dragon.alive=false;
