function updateHud(){document.getElementById('hpText').textContent=Math.ceil(player.hp);document.getElementById('hpBar').style.width=`${100*player.hp/player.maxHp}%`;document.getElementById('xpText').textContent=`${player.xp} / ${player.level*100}`;document.getElementById('xpBar').style.width=`${100*player.xp/(player.level*100)}%`;document.getElementById('gold').textContent=player.gold;document.getElementById('relics').textContent=player.relics;document.getElementById('level').textContent=player.level;document.getElementById('biomeName').textContent=getBiome();document.getElementById('biomeDesc').textContent=inForest(player.x,player.y)?'Every shadow has teeth. Every hollow may hold a treasure.':'Follow the old road. The great powers wait beyond.';updateObjective();let b=bossFocus&&bossFocus.alive?bossFocus:null;document.getElementById('bossbar').classList.toggle('show',!!b);if(b){document.getElementById('bossName').textContent=b.type==='dragon'?'THE ASHEN WYRM':'LORD VEYR, THE NIGHT KING';document.getElementById('bossHp').style.width=`${100*b.hp/b.maxHp}%`}}
function triggerBosses(){if(player.relics>=3&&!bosses.vampire.defeated&&!bosses.vampire.alive&&Math.hypot(player.x-bosses.vampire.x,player.y-bosses.vampire.y)<440){bosses.vampire.alive=true;enemies.push(bosses.vampire);bossFocus=bosses.vampire;toast('The Vampire Lord stirs in Ravenfall Keep!');}if(bosses.vampire.defeated&&!bosses.dragon.defeated&&!bosses.dragon.alive&&Math.hypot(player.x-bosses.dragon.x,player.y-bosses.dragon.y)<500){bosses.dragon.alive=true;enemies.push(bosses.dragon);bossFocus=bosses.dragon;toast('The Ashen Wyrm descends from Ember Crown!')}}
function damagePlayer(amount){if(player.invuln>0||dead)return;player.hp-=amount;player.invuln=.7;shake=7;addFloat(player.x,player.y-22,`-${amount}`,'#ff8670');burst(player.x,player.y,'#a43e3b',7);if(player.hp<=0){player.hp=0;dead=true;document.getElementById('modalTitle').textContent='The Wilds Claim You';document.getElementById('modalText').innerHTML='The shrine remembers your name. Rise again, wayfarer, and finish what you began.';document.getElementById('closeModal').textContent='RISE AT THE SHRINE';document.getElementById('modal').classList.add('show')}}
function hitEnemy(e,damage){if(!e.alive)return;e.hp-=damage;e.hit=.16;burst(e.x,e.y,e.type==='dragon'?'#ff8b52':'#e5c57a',5);addFloat(e.x,e.y-e.r,`-${damage}`);if(e.hp<=0){e.alive=false;player.xp+=e.xp;player.gold+=e.gold;addFloat(e.x,e.y-20,`+${e.gold} crowns`,'#e5ca82');toast(`${e.name} defeated · +${e.xp} XP`);if(e.boss){e.defeated=true;bossFocus=null;document.getElementById('bossbar').classList.remove('show');if(e.type==='vampire'){toast('Lord Veyr falls. The Wyrm has awakened!');}else{won=true;document.getElementById('modalTitle').textContent='The Wilds Are Yours';document.getElementById('modalText').innerHTML='The Ashen Wyrm is no more. Gloamreach will sing of the wayfarer who crossed the dark and brought dawn back to the wilds.';document.getElementById('closeModal').textContent='WANDER THE WILDS';document.getElementById('modal').classList.add('show')}}if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=15;player.hp=Math.min(player.maxHp,player.hp+35);toast(`Level ${player.level} · vitality restored`)}}}
function attack(){if(player.attack>0||dead)return;player.attack=.31;let target=null,closest=85;for(const e of enemies){if(!e.alive)continue;let d=distanceTo(player,e);let angle=Math.atan2(e.y-player.y,e.x-player.x);let diff=Math.atan2(Math.sin(angle-player.face),Math.cos(angle-player.face));if(d<closest&&Math.abs(diff)<1.25){closest=d;target=e}}if(target)hitEnemy(target,Math.round(22+player.level*4));}
function gather(){let near=null,closest=58;for(const l of loot){if(l.got)continue;let d=distanceTo(player,l);if(d<closest){near=l;closest=d}}if(!near){if(distanceTo(player,shrine)<62&&player.hp<player.maxHp){player.hp=player.maxHp;toast('The old shrine restores your vitality');burst(shrine.x,shrine.y,'#e6ce85',20)}else toast('Nothing nearby to gather');return}near.got=true;burst(near.x,near.y,near.type==='relic'?'#e7d076':'#b8d7a1',15);if(near.type==='relic'){player.relics++;player.xp+=80;player.gold+=35;toast(`${near.name} recovered · the old seal stirs`)}else{let coins=10+Math.floor(rand()*27);player.gold+=coins;player.hp=Math.min(player.maxHp,player.hp+12);player.xp+=12;toast(`Forest cache · +${coins} crowns, +12 vitality`)}updateHud()}

function update(dt){elapsed+=dt;if(dead)return;player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy){let len=Math.hypot(dx,dy);dx/=len;dy/=len;player.x=clamp(player.x+dx*player.speed*dt,24,W-24);player.y=clamp(player.y+dy*player.speed*dt,24,H-24);player.face=Math.atan2(dy,dx)}
