for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.from==='enemy'&&Math.hypot(s.x-player.x,s.y-player.y)<player.r+s.r){s.life=0;damagePlayer(s.dmg)}}shots=shots.filter(s=>s.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(const f of floating){f.y-=26*dt;f.life-=dt}floating=floating.filter(f=>f.life>0);triggerBosses();updateHud()}
function pathStroke(points,width,color){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=color;ctx.stroke()}
const roadA=[[70,1280],[340,1260],[680,1250],[930,1080],[1110,900],[1430,865],[1610,900],[1830,990],[2070,1120],[2350,1020],[2570,740],[2650,510]];
const roadB=[[1580,880],[1680,1100],[1840,1300],[2030,1440],[2220,1590],[2410,1790],[2580,1980],[2740,2190]];
function drawGround(cam){ctx.fillStyle='#28352a';ctx.fillRect(0,0,W,H);
// muted upland and woodland clearings
for(const l of landmarks){ctx.save();ctx.globalAlpha=.72;let gr=ctx.createRadialGradient(l.x,l.y,0,l.x,l.y,l.r*1.35);gr.addColorStop(0,l.color);gr.addColorStop(.7,l.color);gr.addColorStop(1,'#28352a00');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(l.x,l.y,l.r*1.35,0,TAU);ctx.fill();ctx.restore()}
