for(const p of [roadA,roadB]){pathStroke(p,64,'#232b23');pathStroke(p,43,'#71634a');pathStroke(p,2,'#9b8660')}
// puddles in the marsh, broken basalt in the ashlands
for(let i=0;i<16;i++){let x=1330+i*39,y=1390+Math.sin(i*2.7)*150;ctx.fillStyle=i%2?'#314b43aa':'#374d45aa';ctx.beginPath();ctx.ellipse(x,y,30+(i%3)*8,13+(i%4)*3,-.4,0,TAU);ctx.fill();ctx.strokeStyle='#7d92735c';ctx.lineWidth=1;ctx.stroke()}
for(let i=0;i<54;i++){let x=2280+(i*137)%640,y=1750+(i*223)%580;ctx.save();ctx.translate(x,y);ctx.rotate(i*.61);ctx.fillStyle=i%2?'#625048':'#51453f';ctx.beginPath();ctx.ellipse(0,0,12+(i%5)*3,5+(i%3)*2,0,0,TAU);ctx.fill();ctx.restore()}
// ground grain and glimmers, only within viewport
