function drawTree(t){ctx.save();ctx.translate(t.x,t.y);ctx.scale(t.h,t.h);let dark=t.tone;ctx.fillStyle='#11191377';ctx.beginPath();ctx.ellipse(8,12,30,20,0,0,TAU);ctx.fill();ctx.fillStyle='#4b4332';ctx.beginPath();ctx.ellipse(0,7,9,13,0,0,TAU);ctx.fill();let c1=dark>.5?'#29442d':'#243b2a',c2=dark>.5?'#365338':'#2e4931';ctx.fillStyle=c1;ctx.beginPath();ctx.arc(-9,-7,22,0,TAU);ctx.arc(9,-10,21,0,TAU);ctx.arc(0,-24,20,0,TAU);ctx.fill();ctx.fillStyle=c2;ctx.beginPath();ctx.arc(-7,-17,14,0,TAU);ctx.arc(8,-21,14,0,TAU);ctx.fill();ctx.fillStyle='#71835a55';ctx.beginPath();ctx.arc(-9,-24,6,0,TAU);ctx.fill();ctx.restore()}
