else if(e.type==='vampire'){ctx.fillStyle='#301e2a';ctx.beginPath();ctx.moveTo(-15,8);ctx.lineTo(-25,29);ctx.lineTo(-8,21);ctx.lineTo(0,34);ctx.lineTo(10,20);ctx.lineTo(24,28);ctx.lineTo(14,3);ctx.closePath();ctx.fill();ctx.fillStyle=e.hit?'#ffd1bb':'#c4a0a0';ctx.beginPath();ctx.arc(0,-8,15,0,TAU);ctx.fill();ctx.fillStyle='#6b2532';ctx.beginPath();ctx.moveTo(-14,-7);ctx.lineTo(-13,-20);ctx.lineTo(-4,-15);ctx.lineTo(0,-22);ctx.lineTo(5,-15);ctx.lineTo(13,-20);ctx.lineTo(15,-5);ctx.closePath();ctx.fill();ctx.fillStyle='#ee5964';ctx.fillRect(-7,-10,3,2);ctx.fillRect(5,-10,3,2);ctx.fillStyle='#e8e2d0';ctx.beginPath();ctx.moveTo(7,-1);ctx.lineTo(10,6);ctx.lineTo(12,-2);ctx.fill()}
else {ctx.fillStyle=e.hit?'#fff0c4':e.color;ctx.beginPath();if(e.type==='wraith'){ctx.arc(0,-3,e.r,Math.PI,0);ctx.lineTo(e.r,13);ctx.lineTo(5,8);ctx.lineTo(-3,15);ctx.lineTo(-10,8);ctx.lineTo(-e.r,13);ctx.closePath()}else{ctx.ellipse(0,1,e.r,e.r*.78,0,0,TAU)}ctx.fill();ctx.fillStyle=e.type==='wraith'?'#dbefe0':'#ded4b3';ctx.fillRect(-6,-5,3,3);ctx.fillRect(4,-5,3,3);if(e.type==='brute'){ctx.fillStyle='#c2a15e';ctx.beginPath();ctx.moveTo(-12,-10);ctx.lineTo(-17,-20);ctx.lineTo(-5,-13);ctx.moveTo(12,-10);ctx.lineTo(17,-20);ctx.lineTo(5,-13);ctx.fill()}}
if(e.boss){ctx.strokeStyle=e.type==='dragon'?'#e59252':'#d36771';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+6+Math.sin(elapsed*3)*2,0,TAU);ctx.stroke()}ctx.restore()}

